function buildRect(x,y,w,h,rx){ return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'"'+(rx?' rx="'+rx+'"':'')+'/>'; }
function buildCircle(cx,cy,r){ return '<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'"/>'; }
function polygonPoints(cx,cy,r,n,rot){ rot=rot||0; var pts=[]; for(var i=0;i<n;i++){ var ang=rot + i*2*Math.PI/n; pts.push((cx+r*Math.cos(ang)).toFixed(2)+','+(cy+r*Math.sin(ang)).toFixed(2)); } return pts.join(' '); }
function buildPolygon(cx,cy,r,n,rot){ return '<polygon points="'+polygonPoints(cx,cy,r,n,rot)+'"/>'; }
function buildStar(cx,cy,rO,rI,points,rot){ rot=(rot==null)?(-Math.PI/2):rot; var pts=[]; for(var i=0;i<points*2;i++){ var r=(i%2===0)?rO:rI; var ang=rot + i*Math.PI/points; pts.push((cx+r*Math.cos(ang)).toFixed(2)+','+(cy+r*Math.sin(ang)).toFixed(2)); } return '<polygon points="'+pts.join(' ')+'"/>'; }
var EXPORTS={ buildRect:buildRect, buildCircle:buildCircle, polygonPoints:polygonPoints, buildPolygon:buildPolygon, buildStar:buildStar };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SvgShapeForgePure = EXPORTS; }
